import { useEffect, useMemo } from 'react';
import {
  ReactFlow,
  Background,
  Controls,
  MiniMap,
  useNodesState,
  useEdgesState,
} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import { Network } from 'lucide-react';

/**
 * AICanvas — renders diagram nodes/edges generated by the backend
 * using React Flow (@xyflow/react).
 *
 * Props:
 *   flowData — { nodes: [...], edges: [...] } from the backend diagram_flow_parser,
 *              or null when no diagram is active.
 */
export default function AICanvas({ flowData, embedded = false }) {
  const initialNodes = useMemo(() => {
    if (!flowData?.nodes?.length) return [];
    return flowData.nodes.map((n) => ({
      id: n.id,
      type: n.type || 'default',
      position: n.position || { x: 0, y: 0 },
      data: { label: n.data?.label || n.id },
    }));
  }, [flowData]);

  const initialEdges = useMemo(() => {
    if (!flowData?.edges?.length) return [];
    return flowData.edges.map((e) => ({
      id: e.id,
      source: e.source,
      target: e.target,
      label: e.label || '',
      type: e.type || 'smoothstep',
      animated: e.animated || false,
    }));
  }, [flowData]);

  const [nodes, setNodes, onNodesChange] = useNodesState([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState([]);

  // React Flow keeps its own editable state. Keep it synchronized when a
  // newly generated map or an older map from history is selected.
  useEffect(() => {
    setNodes(initialNodes);
    setEdges(initialEdges);
  }, [initialNodes, initialEdges, setNodes, setEdges]);

  const isEmpty = !flowData?.nodes?.length;

  const defaultEdgeOptions = useMemo(
    () => ({
      style: { stroke: 'var(--dc-brand)', strokeWidth: 1.5 },
    }),
    []
  );

  return (
    <div
      className="h-full w-full relative"
      style={{
        background: isEmpty ? 'linear-gradient(180deg, rgba(37, 99, 235, 0.025), transparent 65%)' : 'var(--dc-surface-0)',
        border: embedded ? '0' : '1px solid var(--dc-border)',
        borderTop: embedded ? '1px solid var(--dc-border)' : undefined,
        borderRadius: embedded ? 0 : 'var(--dc-radius-md)',
        overflow: 'hidden',
      }}
    >
      {isEmpty ? (
        <div
          className="h-full flex flex-col items-center justify-center px-6 text-center"
          style={{ color: 'var(--dc-text-muted)' }}
        >
          <span className="mb-3 flex h-11 w-11 items-center justify-center rounded-2xl" style={{ background: 'var(--dc-brand-dim)', color: 'var(--dc-brand)' }}><Network size={21} /></span>
          <p className="text-sm font-semibold" style={{ color: 'var(--dc-text-primary)' }}>No context map yet</p>
          <p className="mt-1 text-xs leading-relaxed" style={{ color: 'var(--dc-text-muted)' }}>
            Ask the AI, then use{' '}
            <code
              className="mx-1 px-1.5 py-0.5 rounded"
              style={{
                background: 'var(--dc-brand-dim)',
                color: 'var(--dc-brand-glow)',
                fontSize: '11px',
              }}
            >
              /extract_diagram
            </code>
            to map the answer.
          </p>
        </div>
      ) : (
        <ReactFlow
          nodes={nodes}
          edges={edges}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          defaultEdgeOptions={defaultEdgeOptions}
          fitView
          fitViewOptions={{ padding: 0.2 }}
          proOptions={{ hideAttribution: true }}
          colorMode="light"
        >
          <Background
            color="rgba(71, 85, 105, 0.12)"
            gap={20}
            size={1.5}
          />
          <Controls
            showInteractive={false}
            style={{
              backgroundColor: 'var(--dc-surface-2)',
              borderColor: 'var(--dc-border)',
            }}
          />
          <MiniMap
            nodeColor="var(--dc-brand)"
            maskColor="rgba(226,232,240,0.62)"
            style={{
              backgroundColor: 'var(--dc-surface-0)',
              border: '1px solid var(--dc-border)',
            }}
          />
        </ReactFlow>
      )}
    </div>
  );
}
